import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月3日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-03.md","filePath":"science-log/src/reconstructed/2026-09-03.md"}'),e={name:"science-log/src/reconstructed/2026-09-03.md"};function a(g,r,i,l,c,p){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月3日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月3日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月3日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月3日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-03 为<strong>周四</strong>。CrossRef 精确当日命中：Nature（0028-0836）<strong>6 条，其中仅 1 条 <code>10.1038/s41586-…</code> 研究论文</strong>（其余为 <code>d41586-…</code> 新闻/Briefing，已丢弃）；Science 系（10.1126）<strong>48 条</strong>（含 Science 本体研究论文与 Science Advances / Science Immunology 等）；PNAS（0027-8424）<strong>7 条研究论文</strong>。故科学 5 篇全部取自<strong>当日真实命中</strong>（Nature + Science + PNAS），优先方法新颖、结论具体者。<strong>AI 5 篇</strong>为当日 arXiv cs.AI 提交（submittedDate <code>[202609030000 TO 202609032359]</code>，取前 30 条中遴选）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="⚗️-让酮「长一个碳」-钯催化脱羧重排的协同机理复活了一门-1960-年代的老反应" tabindex="-1">⚗️ 让酮「长一个碳」：钯催化脱羧重排的协同机理复活了一门 1960 年代的老反应 <a class="header-anchor" href="#⚗️-让酮「长一个碳」-钯催化脱羧重排的协同机理复活了一门-1960-年代的老反应" aria-label="Permalink to &quot;⚗️ 让酮「长一个碳」：钯催化脱羧重排的协同机理复活了一门 1960 年代的老反应&quot;">​</a></h3><p><strong>Ketone homologation via palladium-catalysed decarboxylative rearrangement</strong><em>Nature（2026）</em></p><p>把酮<strong>加长一个碳</strong>（同系化，homologation）是有机合成里的经典需求，但传统上难而碎。1960 年就有人报告过 β-羟基羧酸在<strong>电化学氧化</strong>下的<strong>脱羧半频哪醇重排</strong>——理论上一锅就能把羧酸脱掉 CO₂ 并把碳链重排成酮，但此后几十年发展受限：分步的自由基与碳正离子路径<strong>副反应多</strong>，且会<strong>丢掉 α-碳的立体化学信息</strong>。本文用 <strong>Pd(II)/Pd(IV) 催化</strong> 让反应改走<strong>协同机理</strong>：先形成<strong>六元 Pd(IV) 螯合物</strong>，随后<strong>碎裂并伴随 β→α 碳迁移与 CO₂ 挤出</strong>，Pd(IV) 在其中扮演关键角色。绕开高能自由基/碳正离子中间体后，反应能<strong>保住手性</strong>——等于给一门六十年的老反应装上了选择性。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11091-5" target="_blank" rel="noreferrer">10.1038/s41586-026-11091-5</a></p><h3 id="🛡️-肿瘤「偷走」t-细胞的活性氧-prdx1-分泌如何关掉抗肿瘤免疫" tabindex="-1">🛡️ 肿瘤「偷走」T 细胞的活性氧：PRDX1 分泌如何关掉抗肿瘤免疫 <a class="header-anchor" href="#🛡️-肿瘤「偷走」t-细胞的活性氧-prdx1-分泌如何关掉抗肿瘤免疫" aria-label="Permalink to &quot;🛡️ 肿瘤「偷走」T 细胞的活性氧：PRDX1 分泌如何关掉抗肿瘤免疫&quot;">​</a></h3><p><strong>Tumor-derived antioxidants suppress immunity by depriving T cells of reactive oxygen species</strong><em>Science（2026）</em></p><p>活性氧（ROS）既促基因组不稳定、又驱动致癌信号，于是抗氧化疗法一度被视为抗癌思路，但临床<strong>屡屡失败甚至加重病情</strong>。本文给出一个反直觉解释：<strong>T 细胞自身依赖 ROS 做信号转导</strong>。研究发现<strong>肿瘤间质液具有强抗氧化活性</strong>，与抗氧化酶 <strong>peroxiredoxin 1（PRDX1）富集</strong>相关；<strong>胞外 PRDX1</strong> 剥夺 T 细胞的 ROS，从而<strong>阻止那些需要被氧化失活的磷酸酶</strong>被关掉，卡住 <strong>T 细胞受体（TCR）驱动的信号</strong>。这解释了「抗氧化为何反而助癌」——肿瘤把抗氧化酶当成<strong>免疫抑制武器</strong>，提示靶向胞外 PRDX1 可能是新的免疫治疗切入点。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz8203" target="_blank" rel="noreferrer">10.1126/science.adz8203</a></p><h3 id="🪐-宜居带岩质行星-lhs-1140b-正在「漏气」-首次观测到氦逃逸-且逐年变化" tabindex="-1">🪐 宜居带岩质行星 LHS 1140b 正在「漏气」：首次观测到氦逃逸，且逐年变化 <a class="header-anchor" href="#🪐-宜居带岩质行星-lhs-1140b-正在「漏气」-首次观测到氦逃逸-且逐年变化" aria-label="Permalink to &quot;🪐 宜居带岩质行星 LHS 1140b 正在「漏气」：首次观测到氦逃逸，且逐年变化&quot;">​</a></h3><p><strong>Helium escaping from the atmosphere of a nearby rocky exoplanet orbiting in a habitable zone</strong><em>Science（2026）</em></p><p>此前<strong>氦逃逸</strong>只在被强辐照的<strong>气态巨行星</strong>上明确观测到；岩质行星大气的证据一直很少——或许正因为它们<strong>早就逃光了</strong>。本文报告对 <strong>LHS 1140b</strong>（一颗位于近距低质量恒星<strong>宜居带</strong>内的岩质行星）的<strong>近红外光谱观测</strong>：凌星谱显示<strong>氦从其大气逃逸</strong>。关键在时间信息——<strong>2024 年探测到氦吸收，2025 年却没有</strong>，说明<strong>大气逃逸是时变的</strong>。作者据此推断其<strong>上层大气以氦为主、氢被耗尽</strong>，其它挥发分被束缚在更低高度。这为「岩质行星能否保住大气」提供了直接的天体物理样本，也为搜寻宜居世界树立了新的观测窗口。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aea9708" target="_blank" rel="noreferrer">10.1126/science.aea9708</a></p><h3 id="⚛️-用纠缠的-λ–λ-对测最轻超子的电偶极矩-精度比此前提升三个数量级" tabindex="-1">⚛️ 用纠缠的 Λ–Λ̄ 对测最轻超子的电偶极矩：精度比此前提升三个数量级 <a class="header-anchor" href="#⚛️-用纠缠的-λ–λ-对测最轻超子的电偶极矩-精度比此前提升三个数量级" aria-label="Permalink to &quot;⚛️ 用纠缠的 Λ–Λ̄ 对测最轻超子的电偶极矩：精度比此前提升三个数量级&quot;">​</a></h3><p><strong>Measurement of the Λ electric dipole moment with an entangled baryon-antibaryon system</strong><em>Science（2026）</em></p><p>宇宙中<strong>物质压倒反物质</strong>，驱使人们寻找<strong>破坏电荷-宇称（CP）对称性</strong>的新物理。<strong>奇异重子（超子）<strong>是块几乎未开垦的处女地：超子与新物理粒子的相互作用可能诱导出</strong>非零电偶极矩（EDM）</strong>。但超子<strong>寿命极短</strong>，靠自旋进动直接测 EDM 极难。本文提出用<strong>纠缠的 ΛΛ̄ 系统</strong>提取最轻超子 Λ 的 EDM——结果显示<strong>与零一致</strong>，却把<strong>精度较此前提升约三个数量级</strong>。即使没看到信号，「把零测得更准」本身就是对各类新物理模型的<strong>强约束</strong>，是超子 CP 破缺研究的一次方法跃迁。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adx7334" target="_blank" rel="noreferrer">10.1126/science.adx7334</a></p><h3 id="🐟-鱼如何闯「水动力迷宫」-偏航-yaw-介导的侧向迁移与省能策略" tabindex="-1">🐟 鱼如何闯「水动力迷宫」：偏航（yaw）介导的侧向迁移与省能策略 <a class="header-anchor" href="#🐟-鱼如何闯「水动力迷宫」-偏航-yaw-介导的侧向迁移与省能策略" aria-label="Permalink to &quot;🐟 鱼如何闯「水动力迷宫」：偏航（yaw）介导的侧向迁移与省能策略&quot;">​</a></h3><p><strong>Fish navigate a hydrodynamic maze via yaw-mediated lateral migration</strong><em>PNAS（2026）</em></p><p>水环境中<strong>流速梯度与湍流</strong>构成一张不断变化的物理地形图，决定了鱼推进与耗能的约束，而鱼能否<strong>低成本地读懂水动力线索</strong>是其生存关键。作者设计了一条<strong>空间变化的水动力迷宫</strong>——让<strong>平均流与湍流在空间上不均</strong>，从而造出一片可控的<strong>异质流场</strong>，观察鱼的移动策略。结果发现，鱼会通过<strong>偏航（yaw）介导的侧向迁移</strong>逃出<strong>能量不利区</strong>，主动借用流场结构来省力。这揭示了一套<strong>纯被动的流体力学导航机制</strong>：鱼不必「计算」全局最优路线，只需对局部水动力线索做规则性响应，就能在复杂流场中实现<strong>能效最优</strong>的移动。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2613565123" target="_blank" rel="noreferrer">10.1073/pnas.2613565123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎯-极稀疏监督就能逼出推理能力-只用-0-05-的-token" tabindex="-1">🎯 极稀疏监督就能逼出推理能力：只用 0.05% 的 token <a class="header-anchor" href="#🎯-极稀疏监督就能逼出推理能力-只用-0-05-的-token" aria-label="Permalink to &quot;🎯 极稀疏监督就能逼出推理能力：只用 0.05% 的 token&quot;">​</a></h3><p><strong>Extremely Sparse Supervision Incentivizes Reasoning Ability</strong><em>arXiv:2609.04565（2026）</em></p><p>主流后训练方法在<strong>海量 token</strong> 上做优化，隐含假设「有效学习必须 token 密集」。本文在<strong>在线策略蒸馏（on-policy distillation, OPD）</strong> 这一天然<strong>每个生成 token 都带稠密教师监督</strong>的场景里，用 <strong>Qwen3 系列</strong>做了个反直觉发现：推理能力可以靠<strong>极少数 token</strong> 被有效激励——每条推理轨迹<strong>只用一两个 token</strong>（约占总 token 的 <strong>0.05%</strong>），在多数情况下就能<strong>追平甚至超过</strong>全 token 训练。也就是说，把绝大多数生成 token 排除在训练目标外，推理反而更好。这挑战了「监督越密越好」的直觉，指向一个更本质的问题：<strong>稀疏且定向的监督信号，可能比均匀稠密监督更高效地塑造推理行为</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.04565" target="_blank" rel="noreferrer">2609.04565</a></p><h3 id="🔗-静态绑定失效时-用「验证-生成」循环动态适配-llm-上下文" tabindex="-1">🔗 静态绑定失效时：用「验证-生成」循环动态适配 LLM 上下文 <a class="header-anchor" href="#🔗-静态绑定失效时-用「验证-生成」循环动态适配-llm-上下文" aria-label="Permalink to &quot;🔗 静态绑定失效时：用「验证-生成」循环动态适配 LLM 上下文&quot;">​</a></h3><p><strong>Dynamic Adaptation of the LLM Context for Generating Routines with Coupled Semantics</strong><em>arXiv:2609.04570（2026）</em></p><p>LLM 代码生成会在<strong>正确性依赖执行耦合</strong>时失败：<strong>一个例程的含义由另一个例程的运行时行为定义</strong>，这种关系<strong>无法仅从文字描述中解出</strong>——作者称之为<strong>静态绑定（static binding）</strong>。它不限于显式耦合问题，凡正确性依赖<strong>跨组件联合执行行为</strong>时都不同程度存在（从显式交叉耦合优化器，到打包、路由、符号搜索中的隐性联合约束）。本文提出<strong>动态上下文适配</strong>：一个<strong>样本高效的「验证-生成」循环</strong>——<strong>验证智能体</strong>从<strong>执行轨迹</strong>中提取<strong>结构化诊断信息</strong>，作为<strong>类梯度</strong>指导<strong>生成智能体</strong>每轮产出<strong>多个候选</strong>；并由问题导出的<strong>知识图谱</strong>支撑推理。核心思想是：遇到「语义只能在运行时才确定」的问题，就别指望静态 prompt，<strong>让执行反馈来改写上下文</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.04570" target="_blank" rel="noreferrer">2609.04570</a></p><h3 id="🔭-hakken-预测「尚未被记录」的科研关系-填补今日知识的空白" tabindex="-1">🔭 Hakken：预测「尚未被记录」的科研关系，填补今日知识的空白 <a class="header-anchor" href="#🔭-hakken-预测「尚未被记录」的科研关系-填补今日知识的空白" aria-label="Permalink to &quot;🔭 Hakken：预测「尚未被记录」的科研关系，填补今日知识的空白&quot;">​</a></h3><p><strong>Hakken: Predicting future discoveries to fill the gaps in today&#39;s knowledge</strong><em>arXiv:2609.04494（2026）</em></p><p>本文提出 <strong>Hakken</strong>——一个<strong>领域无关的预测与解释系统</strong>，做的是<strong>知识预测（knowledge prediction）</strong>：通过建立<strong>全新的科学概念关系</strong>来增长知识，且这些关系<strong>不局限于既有知识的演绎闭包</strong>（即能提出真正「新」的连接，而非只是推导）。方法上，Hakken 用<strong>基于 transformer 的预测模型</strong>，建立在大规模科研文献抽取的<strong>知识图谱时间序列</strong>上，并<strong>融汇 LLM 的语义知识</strong>，来<strong>预测尚未被记录的关系是否存在、并判定其类型</strong>；随后调用<strong>模型无关的解释框架</strong>，为每个预测附带<strong>可评估的佐证信息</strong>，让科学家能判断这条新关系是否靠谱。在<strong>生物医学域</strong>的实验中，其预测模型<strong>刷新了该任务的基准</strong>。这类系统把「科研发现」当成<strong>可预测的数据问题</strong>，是「AI 科学家」路线的一个具体落地。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.04494" target="_blank" rel="noreferrer">2609.04494</a></p><h3 id="🕵️-把间接提示注入重构成「测试时搜索」问题-攻击强度随算力增长" tabindex="-1">🕵️ 把间接提示注入重构成「测试时搜索」问题：攻击强度随算力增长 <a class="header-anchor" href="#🕵️-把间接提示注入重构成「测试时搜索」问题-攻击强度随算力增长" aria-label="Permalink to &quot;🕵️ 把间接提示注入重构成「测试时搜索」问题：攻击强度随算力增长&quot;">​</a></h3><p><strong>Rethinking Indirect Prompt Injection as a Test-Time Search Problem</strong><em>arXiv:2609.04495（2026）</em></p><p>本文将<strong>间接提示注入（indirect prompt injection）<strong>重新表述为</strong>在一个任务相关的攻击面上做测试时搜索</strong>——该攻击面由<strong>环境、用户任务、注入任务</strong>共同诱导。为落地这一表述，作者提出一个<strong>配备专用搜索挽具（search harness）的智能体攻击者</strong>，执行<strong>环境侦察、对攻击策略的结构化推理、以及基于受害者智能体反馈的自适应评估</strong>。跨异构任务的结果显示：<strong>增大攻击者的测试时算力，能提升漏洞的发现与利用</strong>；消融实验表明<strong>显式的策略管理</strong>对<strong>避免重复搜索、在大预算下维持收益</strong>很重要。核心观点是：智能体安全评估应当<strong>同时刻画攻击者的搜索过程与算力预算</strong>，而不是把「攻击成功率」当成受害者<strong>与预算无关</strong>的固有属性。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.04495" target="_blank" rel="noreferrer">2609.04495</a></p><h3 id="🧩-maxkernel-为-tpu-生成高性能自定义内核的多智能体系统" tabindex="-1">🧩 MaxKernel：为 TPU 生成高性能自定义内核的多智能体系统 <a class="header-anchor" href="#🧩-maxkernel-为-tpu-生成高性能自定义内核的多智能体系统" aria-label="Permalink to &quot;🧩 MaxKernel：为 TPU 生成高性能自定义内核的多智能体系统&quot;">​</a></h3><p><strong>MaxKernel: Agentic Kernel Generation for TPUs</strong><em>arXiv:2609.04523（2026）</em></p><p>为加速器设计并编写<strong>高性能自定义内核</strong>极其复杂，需要深厚的硬件级经验。本文提出 <strong>MaxKernel</strong>——一个<strong>多智能体系统</strong>，把 <strong>LLM 与实时编译器反馈</strong>结合来做内核生成，并实现了<strong>三种范式</strong>：（1）<strong>Human-in-the-Loop（HITL）</strong> 协作式逐步设计；（2）<strong>全自动（Auto）</strong> 智能体，执行由<strong>指标/轨迹驱动</strong>的优化循环；（3）<strong>基于图的自主搜索</strong>，把 Auto 智能体<strong>放大到全局设计空间探索</strong>。三者共享一批<strong>专职子智能体</strong>，分别负责<strong>规划、实现、自调试、测试与硬件剖析</strong>。系统在 <strong>JaxBench</strong> 上评测。这体现了「<strong>智能体 + 编译器反馈</strong>」在系统软件这类<strong>强约束、强验证</strong>领域的一个通用范式：把客观的编译/性能信号当作闭环奖励。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.04523" target="_blank" rel="noreferrer">2609.04523</a></p><hr><blockquote><p>📅 日期：2026-09-03 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',46)])])}const m=t(e,[["render",a]]);export{d as __pageData,m as default};
